from contextlib import contextmanager

from ute_common_config_files.scfc.exceptions import ExactlyOneManagedObjectExpected
from ute_common_config_files.scfc.scfc import Scfc

from ute_fsmaccess import ute_fsmaccess
from ta5g_enb import ta5g_enb
from ute_common_admin.exception import AdminApiConnectionClosedException  # noqa: F401
from ta5g_file_system import ta5g_file_system
from robot.api import logger
import xml.etree.ElementTree as ET
import os
import re
from .importer import import_itertools_zip_longest

zip_longest = import_itertools_zip_longest()


NAMESPACE = 'raml21.xsd'
NAMESPACES = {'ns': NAMESPACE}


class info(object):
    def __init__(self, info_text):
        self.info_text = info_text

    def __call__(self, func):
        def func_with_printed_info(self_arg, moc, *args):
            logger.info(('{} {}'.format(self.info_text, moc.get('distName'))))
            func(self_arg, moc, *args)

        return func_with_printed_info


@contextmanager
def library_session(library_type, setup, teardown):
    lib = library_type()
    setup(lib)
    try:
        yield lib
    finally:
        teardown(lib)


def fsmaccess_session():
    return library_session(ute_fsmaccess,
                           lambda lib_instance: lib_instance.setup_enb_fsm_access(host='192.168.255.129'),
                           lambda lib_instance: lib_instance.teardown_enb_fsm_access())


def get_sw_release():
    with fsmaccess_session() as fsm:
        sw_version = fsm.get_enb_sw_version()
        return sw_version.split('_')[0]


def get_sw_type_from_scfc(scfc_path):
    with open(scfc_path, 'r') as scfc_file:
        for line in scfc_file.readlines():
            if line.lower().find('productvariantplanned') != -1:
                r = re.search('.*productvariantplanned\">(.*)?<', line.lower())
                if r:
                    return r.group(1)
    return False


def is_scfc_for_admin(scfc_path):
    scfc = Scfc(scfc_path)
    try:
        pmtnl_object = scfc.find_single_managed_object('PMTNL')
        if pmtnl_object:
            distname = pmtnl_object.dist_name
            if '/TNL' in distname:
                return True
    except ExactlyOneManagedObjectExpected:
        pass
    return False


def get_config_dir():
    return ta5g_file_system.get_config_directory_path()


def has_only_filename(path):
    return os.path.basename(path) == path


def get_delta_scf_path(path):
    scfc_path = ta5g_enb().get_scfc_file("/tmp/latest_scf.xml")
    sw_type = get_sw_type_from_scfc(scfc_path)
    if sw_type in ['sbts', '5G', 'ltebts']:
        path = path.replace(".xml", ".json")
        logger.info("\nDelta SCFC file name changed to: " + path, also_console=True)
    default_scfc_filepath = os.path.join(get_config_dir(), 'default/', path)
    if os.path.exists(default_scfc_filepath):
        return default_scfc_filepath
    else:
        found_scfc_filepath = os.path.join(get_config_dir(), get_sw_release(), path)
        return found_scfc_filepath


def get_full_scf_path(path):
    if not has_only_filename(path):
        return path
    return os.path.join(get_config_dir(), get_sw_release(), path)


def is_param_changed(param, initial_params):
    name, value = param
    return name in initial_params and not are_params_equal(value, initial_params[name])


def get_changed_params(initial_params, delta_params):
    return (param for param in list(delta_params.items()) if is_param_changed(param, initial_params))


def get_added_params(initial_params, delta_params):
    return (param for name, param in list(delta_params.items()) if name not in initial_params)


def get_deleted_params(initial_params, current_params):
    return ((name, param) for (name, param) in list(initial_params.items()) if name not in current_params)


def get_empty_clone(element):
    return ET.Element(element.tag, element.attrib)


def get_params(moc):
    params = moc.findall('ns:p', NAMESPACES)
    params.extend(moc.findall('ns:list', NAMESPACES))

    return {p.get('name'): p for p in params}


def get_mocs(scf_path):
    scf = ET.parse(scf_path).getroot()
    return {m.get('distName'): m for m in scf.findall('ns:cmData/ns:managedObject', NAMESPACES)}


def are_params_equal(lhs, rhs):
    try:
        lhs_text = lhs.text.strip() if lhs.text is not None else ''
        rhs_text = rhs.text.strip() if rhs.text is not None else ''

        return (
            lhs.tag == rhs.tag
            and lhs.attrib == rhs.attrib
            and lhs_text == rhs_text
            and all(are_params_equal(left, right) for left, right in zip_longest(lhs, rhs))
        )

    except AttributeError:
        return lhs == rhs


class IncorrectOperationTypeError(AttributeError):
    pass
